drogon::HttpAppFramework::instance().enableSession(1200);  // same-site + timeout

void Handler(const HttpRequestPtr &req, std::function<void(const HttpResponsePtr &)> &&cb) {
    auto session = req->session();                 // drogon::Session, server-side
    if (session->find("visits")) {
        session->modify<int>("visits", [](int &v) { ++v; });
    } else {
        session->insert("visits", 1);
    }
    cb(HttpResponse::newHttpJsonResponse({{ "visits", session->get<int>("visits") }}));
}

